const $=id=>document.getElementById(id);
function duration(value){const total=Math.max(0,Math.floor(value/1000));return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function date(value){try{return new Intl.DateTimeFormat('uk-UA',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Kyiv'}).format(new Date(value));}catch{return '';}}
async function request(path,body){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)});if(!response.ok)throw new Error();return response.json();}
const setVisibility=(recording,visible)=>request('/api/recordings/visibility',{id:recording.id,visible});
const deleteRecording=recording=>request('/api/recordings/delete',{id:recording.id});
const manage=body=>request('/api/recordings/manage',body);

function folderToolbar(folders,reload,status){
  const toolbar=document.createElement('div');toolbar.className='recording-folder-toolbar';
  const input=document.createElement('input');input.type='text';input.maxLength=60;input.placeholder='Назва нової папки';input.setAttribute('aria-label','Назва нової папки');
  const create=document.createElement('button');create.type='button';create.className='recording-action';create.textContent='＋ Створити папку';
  create.addEventListener('click',async()=>{const name=input.value.trim();if(!name)return;create.disabled=true;try{await manage({action:'createFolder',name});await reload();}catch{status.textContent='Не вдалося створити папку.';}finally{create.disabled=false;}});
  toolbar.append(input,create);
  for(const folder of folders){const group=document.createElement('div');group.className='recording-folder-chip';const name=document.createElement('span');name.textContent=folder.name;const rename=document.createElement('button');rename.type='button';rename.textContent='Перейменувати';rename.addEventListener('click',async()=>{const next=prompt('Нова назва папки',folder.name)?.trim();if(!next)return;await manage({action:'renameFolder',folderId:folder.id,name:next});await reload();});const remove=document.createElement('button');remove.type='button';remove.textContent='Видалити папку';remove.addEventListener('click',async()=>{if(!confirm(`Видалити папку «${folder.name}»? Записи залишаться без папки.`))return;await manage({action:'deleteFolder',folderId:folder.id});await reload();});group.append(name,rename,remove);toolbar.append(group);}
  return toolbar;
}

async function load(){
  const list=$('studio-recordings-list'),status=$('studio-recordings-status');if(!list)return;status.textContent='Оновлюємо список…';
  try{const response=await fetch('/api/recordings',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error();const {recordings=[],folders=[]}=await response.json();list.replaceChildren();list.append(folderToolbar(folders,load,status));
    for(const recording of recordings){const row=document.createElement('article');row.className='studio-recording-row';const copy=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('span');title.textContent=recording.premiere?'E-Transport · ПОСТІЙНА ПРЕМ’ЄРА':'E-Transport · запис презентації';const folder=folders.find(item=>item.id===recording.folderId);meta.textContent=`${date(recording.recordedAt)} · ${duration(recording.duration)} · ${recording.premiere?'Не показується у «Записах»':recording.visible?'Відкритий для людей':'Прихований'} · ${folder?.name||'Без папки'}`;copy.append(title,meta);
      const folderSelect=document.createElement('select');folderSelect.className='recording-folder-select';folderSelect.setAttribute('aria-label','Перемістити запис у папку');folderSelect.append(new Option('Без папки',''),...folders.map(item=>new Option(item.name,item.id)));folderSelect.value=recording.folderId||'';folderSelect.addEventListener('change',async()=>{folderSelect.disabled=true;try{await manage({action:'moveRecording',id:recording.id,destination:folderSelect.value});await load();}catch{status.textContent='Не вдалося перемістити запис.';}finally{folderSelect.disabled=false;}});
      const actions=document.createElement('div'),download=document.createElement('a'),premiere=document.createElement('button'),toggle=document.createElement('button'),remove=document.createElement('button');download.href=recording.downloadUrl||`${recording.url}?download=1`;download.textContent='Скачати';download.className='recording-action';download.download='IK-webinar.'+(recording.contentType==='video/mp4'?'mp4':'webm');premiere.type='button';premiere.className='recording-action';premiere.textContent=recording.premiere?'Зняти з прем’єри':'Зробити постійною прем’єрою';premiere.addEventListener('click',async()=>{premiere.disabled=true;try{await manage({action:'setPremiere',id:recording.premiere?'':recording.id});await load();status.textContent=recording.premiere?'Прем’єрний запис відключено.':'Запис призначено постійною прем’єрою й прибрано з клієнтських «Записів».';}catch{status.textContent='Не вдалося змінити прем’єрний запис.';}finally{premiere.disabled=false;}});toggle.type='button';toggle.className='recording-action';toggle.textContent=recording.visible?'Сховати':'Відкрити для людей';toggle.disabled=recording.premiere;toggle.addEventListener('click',async()=>{toggle.disabled=true;try{await setVisibility(recording,!recording.visible);await load();}catch{status.textContent='Не вдалося змінити видимість.';}finally{toggle.disabled=false;}});remove.type='button';remove.className='recording-action recording-delete';remove.textContent='Видалити';remove.addEventListener('click',async()=>{if(!confirm('Видалити цей запис назавжди?'))return;remove.disabled=true;try{await deleteRecording(recording);await load();status.textContent='Запис видалено.';}catch{status.textContent='Не вдалося видалити запис.';}finally{remove.disabled=false;}});actions.append(download,premiere,toggle,remove);row.append(copy,folderSelect,actions);list.append(row);}
    status.textContent=recordings.length?`Збережено записів: ${recordings.length}`:'Після першого запису він з’явиться тут.';
  }catch{status.textContent='Список записів тимчасово недоступний.';}
}
window.addEventListener('recording:published',load);window.addEventListener('recording:visibility',load);load();
